[CmdletBinding()]
param(
    [string]$ProjectRoot = (Get-Location).Path,
    [string]$PagePath = 'frontend\pages\system-operations\dispatch.html'
)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$kedcoRoot = (Resolve-Path -LiteralPath $ProjectRoot).Path
$kedcoUtf8 = New-Object System.Text.UTF8Encoding -ArgumentList $false, $true
$kedcoPayload = ''
$kedcoMemory = New-Object System.IO.MemoryStream -ArgumentList (,[Convert]::FromBase64String($kedcoPayload))
$kedcoGzip = New-Object System.IO.Compression.GZipStream -ArgumentList $kedcoMemory, ([System.IO.Compression.CompressionMode]::Decompress)
$kedcoReader = New-Object System.IO.StreamReader -ArgumentList $kedcoGzip, $kedcoUtf8
try { $kedcoDefinitions = $kedcoReader.ReadToEnd() | ConvertFrom-Json }
finally { $kedcoReader.Dispose(); $kedcoMemory.Dispose() }

$kedcoWork = New-Object System.Collections.Generic.List[object]
# Validate both files and build both results before touching either original.
foreach ($kedcoFile in $kedcoDefinitions.files) {
    $kedcoRelative = if ($kedcoFile.kind -eq 'page') { $PagePath } else { [string]$kedcoFile.path }
    $kedcoPath = if ([System.IO.Path]::IsPathRooted($kedcoRelative)) { $kedcoRelative } else { Join-Path $kedcoRoot $kedcoRelative }
    if (-not (Test-Path -LiteralPath $kedcoPath -PathType Leaf)) { throw ('Required file not found: ' + $kedcoPath + '. No files were changed.') }
    $kedcoRaw = [System.IO.File]::ReadAllText($kedcoPath, $kedcoUtf8)
    $kedcoText = $kedcoRaw.Replace("`r`n", "`n")
    foreach ($kedcoChange in $kedcoFile.changes) {
        $kedcoNew = [string]$kedcoChange.new
        if ([regex]::Matches($kedcoText, [regex]::Escape($kedcoNew)).Count -eq 1) { continue }
        $kedcoCandidates = @([string]$kedcoChange.old)
        if ($kedcoChange.PSObject.Properties['oldAlternatives']) { $kedcoCandidates += @($kedcoChange.oldAlternatives | ForEach-Object { [string]$_ }) }
        $kedcoMatches = @($kedcoCandidates | Where-Object { [regex]::Matches($kedcoText, [regex]::Escape($_)).Count -eq 1 })
        if ($kedcoMatches.Count -ne 1) {
            throw ('Cannot match the current file section: ' + $kedcoPath + ' / ' + $kedcoChange.description + '. No files were changed.')
        }
        $kedcoText = $kedcoText.Replace([string]$kedcoMatches[0], $kedcoNew)
    }
    if ($kedcoFile.kind -eq 'page') {
        if (-not $kedcoText.Contains('data-kedco-eforms-page="dispatch"')) { throw 'The selected page is not Dispatch. No files were changed.' }
        foreach ($kedcoId in @('hourlyChart', 'dailyChart', 'kedcoDispatchApprovedChart7Style', 'kedcoDispatchApprovedChart7Script')) {
            if ([regex]::Matches($kedcoText, [regex]::Escape('id="' + $kedcoId + '"')).Count -ne 1) { throw ('Duplicate or missing page ID: ' + $kedcoId + '. No files were changed.') }
        }
    }
    if ($kedcoRaw.Contains("`r`n")) { $kedcoText = $kedcoText.Replace("`n", "`r`n") }
    $kedcoWork.Add([pscustomobject]@{Path=$kedcoPath;Text=$kedcoText;Changed=($kedcoText -ne $kedcoRaw);Backup='';Temp='';Attempted=$false})
}
$kedcoChanged = @($kedcoWork | Where-Object { $_.Changed })
if ($kedcoChanged.Count -eq 0) { Write-Host 'The current-hour overview fix is already installed.' -ForegroundColor Green; exit 0 }

try {
    # Back up and stage EVERY changed file before starting the replacement.
    foreach ($kedcoItem in $kedcoChanged) {
        $kedcoSuffix = (Get-Date -Format 'yyyyMMdd-HHmmss-fff') + '-' + [guid]::NewGuid().ToString('N')
        $kedcoItem.Backup = $kedcoItem.Path + '.current-hour-overview-backup-' + $kedcoSuffix + '.bak'
        $kedcoItem.Temp = $kedcoItem.Path + '.' + $kedcoSuffix + '.tmp'
        Copy-Item -LiteralPath $kedcoItem.Path -Destination $kedcoItem.Backup
        [System.IO.File]::WriteAllText($kedcoItem.Temp, $kedcoItem.Text, $kedcoUtf8)
    }
    foreach ($kedcoItem in $kedcoChanged) {
        $kedcoItem.Attempted = $true
        [System.IO.File]::Copy($kedcoItem.Temp, $kedcoItem.Path, $true)
    }
} catch {
    $kedcoError = $_
    foreach ($kedcoItem in $kedcoChanged) {
        if ($kedcoItem.Attempted) {
            try { [System.IO.File]::Copy($kedcoItem.Backup, $kedcoItem.Path, $true) }
            catch { Write-Warning ('Restore this file from: ' + $kedcoItem.Backup) }
        }
    }
    throw $kedcoError
} finally {
    foreach ($kedcoItem in $kedcoChanged) {
        if ($kedcoItem.Temp -and (Test-Path -LiteralPath $kedcoItem.Temp)) { Remove-Item -LiteralPath $kedcoItem.Temp -Force }
    }
}
foreach ($kedcoItem in $kedcoChanged) { Write-Host ('Updated: ' + $kedcoItem.Path) -ForegroundColor Green; Write-Host ('Backup: ' + $kedcoItem.Backup) }
Write-Host 'LIVE overview uses the current Africa/Lagos hour. Historical Reference views keep the selected date.'
Write-Host 'Press Ctrl+F5. Compare the overview with the current Lagos-hour column of the load-flow sheet.' -ForegroundColor Cyan
